package task_tasks;

public class Conditionifelse {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		int marks = 75;
		if(marks <= 34) {
			System.out.println("failed");
		}
		else if(marks >= 35 <= 50){
			System.out.println("grade c");
		}
		else if(marks >= 51 <= 75) {
			System.out.println("grade b");
		}
		else {
			System.out.println("grade a");
		}

	}

}
